WITH flattened_attrs AS (SELECT id, host, log_ts, status_code, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region FROM app_logs WHERE status_code > 392) SELECT id, host, duration_sec, MIN(status_code) OVER w_recent AS running_min_status_code, MAX(status_code) OVER w_recent AS running_max_status_code, COUNT(status_code) OVER w_recent AS running_count_status_code FROM flattened_attrs WINDOW w_recent AS (PARTITION BY host ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
